import React, { useState, useEffect, useRef } from 'react';
import './PixelArtChat.css';

// Pixel art agent images
import agentNeutral from './assets/agent-neutral.png';
import agentHappy from './assets/agent-happy.png';
import agentConfused from './assets/agent-confused.png';
import agentThinking from './assets/agent-thinking.png';

const PixelArtChat = () => {
  const [messages, setMessages] = useState([]);
  const [inputMessage, setInputMessage] = useState('');
  const [role, setRole] = useState('Frontend Developer');
  const [agentExpression, setAgentExpression] = useState('neutral');
  const messagesEndRef = useRef(null);

  const agentExpressions = {
    neutral: agentNeutral,
    happy: agentHappy,
    confused: agentConfused,
    thinking: agentThinking
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const addMessage = (text, sender, type = '') => {
    setMessages((prev) => [...prev, { text, sender, type }]);
    
    // Update agent expression based on message type
    if (type === 'error') {
      setAgentExpression('confused');
    } else if (sender === 'bot' && !type) {
      const happyWords = ['great', 'excellent', 'good', 'perfect'];
      const isPositive = happyWords.some(word => text.toLowerCase().includes(word));
      setAgentExpression(isPositive ? 'happy' : 'neutral');
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();
    if (!inputMessage.trim()) return;

    addMessage(inputMessage, 'user');
    setAgentExpression('thinking');

    try {
      const response = await fetch('http://localhost:4001/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: inputMessage, role }),
      });

      const data = await response.json();
      addMessage(data.response || 'No response from server.', 'bot');
    } catch (error) {
      console.error('Error:', error);
      addMessage('Error: Unable to communicate with the server.', 'bot', 'error');
    }

    setInputMessage('');
  };

  const handleWrapUp = async () => {
    setAgentExpression('thinking');
    try {
      const history = messages
        .map((msg) => `${msg.sender === 'user' ? 'Candidate' : 'Interviewer'}: ${msg.text}`)
        .join('\n');

      const response = await fetch('http://localhost:4001/api/chat', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ message: '__WRAP_UP__', role, history }),
      });

      const data = await response.json();
      addMessage(data.response || 'No response from server.', 'bot');
    } catch (error) {
      console.error('Error:', error);
      addMessage('Error: Could not finish the interview.', 'bot', 'error');
    }
  };

  const handleFeedback = async () => {
    if (!inputMessage.trim()) {
      addMessage('⚠️ Please enter your feedback.', 'bot', 'error');
      return;
    }

    setAgentExpression('thinking');
    try {
      const response = await fetch('http://localhost:3002/api/feedback', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ feedback: inputMessage, role }),
      });

      const data = await response.json();

      if (response.ok) {
        addMessage('✅ Feedback submitted successfully!', 'bot', 'success');
        setInputMessage('');
      } else {
        addMessage(`❌ Failed: ${data.error}`, 'bot', 'error');
      }
    } catch (error) {
      console.error('Error sending feedback:', error);
      addMessage('❌ Error: Could not send feedback.', 'bot', 'error');
    }
  };

  return (
    <div className="pixel-chat-container">
      <div className="pixel-scene">
        <img 
          src={agentExpressions[agentExpression]} 
          alt="Pixel Art Agent"
          className="pixel-agent"
        />
        <h2 className="pixel-header">Mock Interview Chatbot</h2>
      </div>
      
      <div className="chat-ui">
        <div className="role-selector">
          <select 
            value={role} 
            onChange={(e) => setRole(e.target.value)} 
            className="pixel-select"
          >
            <option value="Frontend Developer">Frontend Developer</option>
            <option value="Backend Developer">Backend Developer</option>
            <option value="Data Scientist">Data Scientist</option>
            <option value="UX Designer">UX Designer</option>
          </select>
        </div>

        <div className="chat-history">
          {messages.map((msg, i) => (
            <div 
              key={i} 
              className={`message ${msg.sender} ${msg.type || ''}`}
            >
              {msg.text}
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>
        
        <form onSubmit={handleSubmit} className="input-area">
          <input
            type="text"
            value={inputMessage}
            onChange={(e) => setInputMessage(e.target.value)}
            placeholder="Your response or feedback..."
            className="pixel-input"
          />
          <button type="submit" className="pixel-button">
            Send
          </button>
        </form>

        <div className="bottom-buttons">
          <button 
            type="button" 
            onClick={handleFeedback} 
            className="pixel-button red-button"
          >
            Submit Feedback
          </button>
          <button 
            type="button" 
            onClick={handleWrapUp} 
            className="pixel-button red-button"
          >
            Finish Interview
          </button>
        </div>
      </div>
    </div>
  );
};

export default PixelArtChat;
